/**
 * Calculate the `z2` of an overlapped progress element.
 *
 * `maxVal - val % maxVal` makes the element of a smaller value be rendered
 * above the element of a bigger value. But the result becomes negative when
 * `maxVal` is negative (a legit config like `min: -100, max: -10`), and a
 * negative `z2` is not a valid ordering value: the progress ends up hidden
 * behind the axis line. Offsetting the result by `2 * |maxVal|` when
 * `maxVal` is negative keeps exactly the same relative ordering while
 * guaranteeing a non-negative `z2`. Gauges with a positive `max` are not
 * affected at all.
 */
function getProgressZ2(maxVal: number, val: number): number {
    if (!isFinite(maxVal) || maxVal === 0) {
        return 0;
    }
    const z2 = maxVal - (val % maxVal);
    if (!isFinite(z2)) {
        return 0;
    }
    // `maxVal < 0` implies `z2 < 0` here, shift it into the non-negative range.
    return maxVal < 0 ? z2 - 2 * maxVal : z2;
}

