            // (axisLine sectors don't, pointers are disabled in these cases).
            const dataIndex = getECData(el).dataIndex;
            if (el.type === 'sector' && dataIndex != null) {
                z2List[dataIndex] = (el as Displayable).z2;
            }
        }
        return z2List;
    }

    function setGaugeOption(min: number, max: number, values: number[]): void {
        chart.setOption({
            animation: false,
            series: [{
                type: 'gauge',
                min: min,
                max: max,
                pointer: {
                    show: false
                },
                progress: {
                    show: true,
                    overlap: true
                },
                data: values.map(function (val) {
                    return { value: val };
                })
            }]
        });
    }

    it('z2 of progress should not be negative when max is negative', function () {
        setGaugeOption(-100, -10, [-95, -63, -22]);

        const z2List = getProgressZ2List();
        expect(z2List.length).toEqual(3);

        for (let i = 0; i < z2List.length; i++) {
            expect(typeof z2List[i]).toEqual('number');
            expect(isFinite(z2List[i])).toEqual(true);
            expect(z2List[i]).toBeGreaterThanOrEqual(0);
        }

        // Relative order must be preserved: a bigger value is placed below
        // (smaller z2) so that the smaller value stays visible.
        expect(z2List[0]).toBeGreaterThan(z2List[1]);
        expect(z2List[1]).toBeGreaterThan(z2List[2]);
    });

    it('z2 of progress should keep the original values when max is positive', function () {
        setGaugeOption(0, 100, [20, 40, 60]);

        expect(getProgressZ2List()).toEqual([80, 60, 40]);
    });

