import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, getECModel } from '../../../core/utHelper';
import { getECData } from '@/src/util/innerStore';
import SeriesModel from '@/src/model/Series';

describe('sunburst_emphasis_focus', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function setSunburstOption(focus: string): void {
        chart.setOption({
            animation: false,
            series: [{
                type: 'sunburst',
                emphasis: {
                    focus: focus
                },
                data: [{
                    name: 'A',
                    children: [{
                        name: 'A1',
                        children: [{
                            name: 'A1a',
                            value: 3
                        }]
                    }, {
                        name: 'A2',
                        value: 4
                    }]
                }, {
                    name: 'B',
                    value: 5
                }]
            }]
        });
    }

    function getDataIndexByName(name: string): number {
        const seriesModel = getECModel(chart).getSeriesByIndex(0) as SeriesModel;
        const data = seriesModel.getData();
        for (let i = 0; i < data.count(); i++) {
            if (data.getName(i) === name) {
                return i;
            }
        }
        return -1;
    }

    function getFocusOfNode(name: string): number[] {
        const dataIndex = getDataIndexByName(name);
        const els = getGraphicElements(chart, 'series', 0);
        for (let i = 0; i < els.length; i++) {
            const ecData = getECData(els[i]);
            if (els[i].type === 'sector' && ecData.dataIndex === dataIndex) {
                return ecData.focus as number[];
            }
        }
        return null;
    }

    it('focus_relative_includes_ancestors_and_descendants', function () {
        setSunburstOption('relative');

        const focus = getFocusOfNode('A1');
        expect(focus).toBeInstanceOf(Array);

        // Self
        expect(focus).toContain(getDataIndexByName('A1'));
        // Ancestor
        expect(focus).toContain(getDataIndexByName('A'));
        // Descendant
        expect(focus).toContain(getDataIndexByName('A1a'));
        // Neither ancestor nor descendant
        expect(focus).not.toContain(getDataIndexByName('A2'));
        expect(focus).not.toContain(getDataIndexByName('B'));
    });

    it('focus_ancestor_keeps_its_semantics', function () {
        setSunburstOption('ancestor');

        const focus = getFocusOfNode('A1');
        expect(focus).toBeInstanceOf(Array);
        expect(focus).toContain(getDataIndexByName('A1'));
        expect(focus).toContain(getDataIndexByName('A'));
        expect(focus).not.toContain(getDataIndexByName('A1a'));
    });

    it('focus_descendant_keeps_its_semantics', function () {
        setSunburstOption('descendant');

        const focus = getFocusOfNode('A1');
        expect(focus).toBeInstanceOf(Array);
        expect(focus).toContain(getDataIndexByName('A1'));
        expect(focus).toContain(getDataIndexByName('A1a'));
        expect(focus).not.toContain(getDataIndexByName('A'));
    });

    it('focus_self_is_not_converted_to_indices', function () {
        setSunburstOption('self');

        expect(getFocusOfNode('A1') as unknown as string).toEqual('self');
    });

});

