import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, getECModel } from '../../../core/utHelper';
import { getECData } from '@/src/util/innerStore';
import SeriesModel from '@/src/model/Series';
import Displayable from 'zrender/src/graphic/Displayable';

describe('treemap_cursor', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function getDataIndexByName(name: string): number {
        const seriesModel = getECModel(chart).getSeriesByIndex(0) as SeriesModel;
        const data = seriesModel.getData();
        for (let i = 0; i < data.count(); i++) {
            if (data.getName(i) === name) {
                return i;
            }
        }
        return -1;
    }

    function getCursorsOfNode(name: string): string[] {
        const dataIndex = getDataIndexByName(name);
        const cursors: string[] = [];
        const els = getGraphicElements(chart, 'series', 0);
        for (let i = 0; i < els.length; i++) {
            const el = els[i];
            if (el.type === 'rect' && getECData(el).dataIndex === dataIndex) {
                cursors.push((el as Displayable).cursor);
            }
        }
        return cursors;
    }

    it('itemStyle_cursor_applied_on_node_content', function () {
        chart.setOption({
            animation: false,
            series: [{
                type: 'treemap',
                animation: false,
                data: [{
                    name: 'a',
                    value: 10,
                    itemStyle: {
                        cursor: 'crosshair'
                    }
                }, {
                    name: 'b',
                    value: 5
                }]
            }]
        });

        const cursorsA = getCursorsOfNode('a');
        expect(cursorsA.length).toBeGreaterThan(0);
        for (let i = 0; i < cursorsA.length; i++) {
            expect(cursorsA[i]).toEqual('crosshair');
        }

        // Omitted => default behaviour ('pointer' is the zrender default).
        const cursorsB = getCursorsOfNode('b');
        expect(cursorsB.length).toBeGreaterThan(0);
        for (let i = 0; i < cursorsB.length; i++) {
            expect(cursorsB[i]).toEqual('pointer');
        }
    });

    it('itemStyle_cursor_from_level_and_series_cascade', function () {
        chart.setOption({
            animation: false,
            series: [{
                type: 'treemap',
                animation: false,
                itemStyle: {
                    cursor: 'help'
                },
                levels: [{}, {
                    itemStyle: {
                        cursor: 'move'
                    }
                }],
                data: [{
                    name: 'a',
                    value: 10
                }, {
                    name: 'b',
                    value: 5,
                    itemStyle: {
                        cursor: 'not-allowed'
                    }
                }]
            }]
        });

        // Level option wins over the series option.
        const cursorsA = getCursorsOfNode('a');
        expect(cursorsA.length).toBeGreaterThan(0);
        for (let i = 0; i < cursorsA.length; i++) {
            expect(cursorsA[i]).toEqual('move');
        }

        // Node option wins over the level option.
        const cursorsB = getCursorsOfNode('b');
        expect(cursorsB.length).toBeGreaterThan(0);
        for (let i = 0; i < cursorsB.length; i++) {
            expect(cursorsB[i]).toEqual('not-allowed');
        }
    });

});

