/**
 * Get ring area of cartesian.
 * Area will have a contain function to determine if a point is in the coordinate system.
 *
 * @param tolerance Expand the ring by `tolerance` pixel in the radial
 *        direction. Useful for clipping, where the content that sits
 *        exactly on the boundary of the axis extent (the stroke of a line,
 *        a symbol, the border of a bar ...) should not be cut off.
 *        `r0` is never expanded below `0`.
 */
getArea(tolerance?: number): PolarArea {
    tolerance = tolerance || 0;

    const angleAxis = this.getAngleAxis();
    const radiusAxis = this.getRadiusAxis();

    const radiusExtent = radiusAxis.getExtent().slice();
    radiusExtent[0] > radiusExtent[1] && radiusExtent.reverse();
    const angleExtent = angleAxis.getExtent();

    const RADIAN = Math.PI / 180;

    return {
        cx: this.cx,
        cy: this.cy,
        r0: Math.max(radiusExtent[0] - tolerance, 0),
        r: radiusExtent[1] + tolerance,
        startAngle: -angleExtent[0] * RADIAN,
        endAngle: -angleExtent[1] * RADIAN,
        clockwise: angleAxis.inverse,
        contain(x: number, y: number) {
            // It's a ring shape.
            // Start angle and end angle don't matter
            const dx = x - this.cx;
            const dy = y - this.cy;
            // minus a tiny value 1e-4 to avoid being clipped unexpectedly
            const d2 = dx * dx + dy * dy - 1e-4;
            const r = this.r;
            const r0 = this.r0;

            return d2 <= r * r && d2 >= r0 * r0;
        }
    };
}

