function createPolarClipPath(
    polar: Polar,
    hasAnimation: boolean,
    seriesModel: SeriesModelWithLineWidth
) {
    const lineWidth = seriesModel.get(['lineStyle', 'width']) || 2;
    // Expand the clip path a bit in the radial direction, to avoid the content
    // that sits exactly on the boundary of the axis extent (the stroke of a
    // line, the border of a bar, a symbol ...) being clipped and looking
    // thinner. Same as what `createGridClipPath` does for cartesian.
    const sectorArea = polar.getArea(lineWidth / 2);
    // Avoid float number rounding error for symbol on the edge of axis extent.

    const r0 = round(sectorArea.r0, 1);
    const r = round(sectorArea.r, 1);

    const startAngle = sectorArea.startAngle;
    // The extent of the angle axis is shrunk by one band when it is a category
    // axis with `boundaryGap: false` (see `polarCreator`), so that the first
    // and the last category are not placed on the same angle. The clip path,
    // however, must still cover the whole circle in that case, otherwise the
    // content around the seam is cut off unexpectedly.
    const endAngle = isAngleAxisFullCircle(polar)
        ? startAngle + (sectorArea.clockwise ? 1 : -1) * Math.PI * 2
        : sectorArea.endAngle;

    const clipPath = new graphic.Sector({
        shape: {
            cx: round(polar.cx, 1),
            cy: round(polar.cy, 1),
            r0: r0,
            r: r,
            startAngle: startAngle,
            endAngle: endAngle,
            clockwise: sectorArea.clockwise
        }
    });

    if (hasAnimation) {
        const isRadial = polar.getBaseAxis().dim === 'angle';

        if (isRadial) {
            clipPath.shape.endAngle = startAngle;
        }
        else {
            clipPath.shape.r = r0;
        }

        graphic.initProps(clipPath, {
            shape: {
                endAngle: endAngle,
                r: r
            }
        }, seriesModel);
    }
    return clipPath;
}

/**
 * Whether the angle axis is configured to cover the whole circle, no matter
 * whether its extent has been shrunk by one band (`boundaryGap: false` on a
 * category axis).
 */
function isAngleAxisFullCircle(polar: Polar): boolean {
    const angleAxisModel = polar.getAngleAxis().model;
    const startAngle = angleAxisModel.get('startAngle');
    const endAngle = angleAxisModel.get('endAngle');
    return endAngle == null || startAngle == null
        || Math.abs(endAngle - startAngle) >= 360 - 1e-4;
}

