import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, getECModel } from '../../../core/utHelper';
import SeriesModel from '@/src/model/Series';
import Polar from '@/src/coord/polar/Polar';
import Sector from 'zrender/src/graphic/shape/Sector';
import Element from 'zrender/src/Element';

const PI2 = Math.PI * 2;

describe('polar_clip', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 500 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function getPolar(): Polar {
        const seriesModel = getECModel(chart).getSeriesByIndex(0) as SeriesModel;
        return seriesModel.coordinateSystem as unknown as Polar;
    }

    function getSectorClipPath(): Sector {
        const els = getGraphicElements(chart, 'series', 0);
        for (let i = 0; i < els.length; i++) {
            const clipPath = (els[i] as Element).getClipPath();
            if (clipPath && clipPath.type === 'sector') {
                return clipPath as Sector;
            }
        }
        return null;
    }

    function setPolarLineOption(angleAxis: object): void {
        chart.setOption({
            animation: false,
            polar: {},
            angleAxis: angleAxis,
            radiusAxis: {},
            series: [{
                type: 'line',
                coordinateSystem: 'polar',
                lineStyle: {
                    width: 10
                },
                data: [11, 22, 33, 44, 55]
            }]
        }, true);
    }

    it('getArea_tolerance_expands_the_radius_extent', function () {
        setPolarLineOption({
            type: 'category',
            data: ['a', 'b', 'c', 'd', 'e']
        });

        const polar = getPolar();
        const area = polar.getArea();
        const expanded = polar.getArea(5);

        expect(expanded.r).toBeCloseTo(area.r + 5, 6);
        // `r0` is never expanded below 0.
        expect(area.r0).toEqual(0);
        expect(expanded.r0).toEqual(0);
        // Not affected.
        expect(expanded.startAngle).toBeCloseTo(area.startAngle, 6);
        expect(expanded.endAngle).toBeCloseTo(area.endAngle, 6);
    });

    it('getArea_tolerance_does_not_shrink_inner_radius_below_zero', function () {
        chart.setOption({
            animation: false,
            polar: {},
            angleAxis: { type: 'category', data: ['a', 'b'] },
            radiusAxis: {},
            series: [{
                type: 'line',
                coordinateSystem: 'polar',
                data: [1, 2]
            }]
        }, true);

        const polar = getPolar();
        expect(polar.getArea(1000).r0).toEqual(0);
    });

    it('clip_path_covers_whole_circle_when_angle_axis_does', function () {
        // `boundaryGap: false` shrinks the extent of the angle axis by one
        // band, but the axis still covers the whole circle, so the content
        // around the seam must not be clipped.
        setPolarLineOption({
            type: 'category',
            boundaryGap: false,
            data: ['a', 'b', 'c', 'd', 'e']
        });

        const clipPath = getSectorClipPath();
        expect(clipPath).not.toEqual(null);
        expect(Math.abs(clipPath.shape.endAngle - clipPath.shape.startAngle)).toBeCloseTo(PI2, 6);

        // The clip radius is expanded by half of the line width so that the
        // stroke on the edge of the axis extent is not cut in half.
        const area = getPolar().getArea();
        expect(clipPath.shape.r).toBeCloseTo(area.r + 5, 6);
        expect(clipPath.shape.r0).toEqual(0);
    });

    it('clip_path_covers_whole_circle_for_default_angle_axis', function () {
        setPolarLineOption({
            type: 'category',
            data: ['a', 'b', 'c', 'd', 'e']
        });

        const clipPath = getSectorClipPath();
        expect(clipPath).not.toEqual(null);
        expect(Math.abs(clipPath.shape.endAngle - clipPath.shape.startAngle)).toBeCloseTo(PI2, 6);
    });

    it('clip_path_keeps_partial_angle_range', function () {
        // A polar that only covers a part of the circle should still clip.
        setPolarLineOption({
            type: 'value',
            startAngle: 90,
            endAngle: 0
        });

        const clipPath = getSectorClipPath();
        expect(clipPath).not.toEqual(null);
        const span = Math.abs(clipPath.shape.endAngle - clipPath.shape.startAngle);
        expect(span).toBeCloseTo(Math.PI / 2, 6);
    });

});
